#'
#' @export
DynamicTable <- function(
    data,
    tc = 5) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("DynamicTable requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- DynamicTableOptions$new(
        tc = tc)

    analysis <- DynamicTableClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

